const pages={market:'Market Returns',test:'Backtester',compare:'Strategy Comparison',angel:'Angel One SmartAPI',depth:'Live Market Depth',contact:'Contact'};
let imports=[],saved=[],database,lastRun=null,marketSymbol='SENSEX',marketRange='1 year',chosen='',serial=0;
const heading=(group,title,text,action='')=>'<div class="head"><div><div class="ey">'+group+'</div><h1>'+title+'</h1><p class="sub">'+text+'</p></div>'+action+'</div>';
const metrics=items=>'<div class="metrics">'+items.map(([a,b])=>'<div><small>'+a+'</small><b>'+b+'</b></div>').join('')+'</div>';
const input=(label,id,val,type='text',attr='')=>'<label>'+label+'<input required id="'+id+'" type="'+type+'" value="'+esc(val)+'" '+attr+'></label>';
const select=(label,id,items)=>'<label>'+label+'<select id="'+id+'">'+items.map(x=>'<option>'+esc(x)+'</option>').join('')+'</select></label>';
const note=x=>'<p class="hint">'+x+'</p>',empty=x=>'<div class="empty">'+x+'</div>';
const importButton='<button onclick="importDialog()">⇧ &nbsp;Import CSV</button>';
async function boot(){try{database=await new Promise((res,rej)=>{let q=indexedDB.open('equity-atlas-private',1);q.onupgradeneeded=()=>{q.result.createObjectStore('files',{keyPath:'id'});q.result.createObjectStore('runs',{keyPath:'id'})};q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});for(let k of ['files','runs']){let a=await new Promise(res=>{let q=database.transaction(k).objectStore(k).getAll();q.onsuccess=()=>res(q.result)});if(k==='files')imports=a;else saved=a}}catch{}window.onhashchange=route;route()}
async function persist(store,item){if(!database){alert('This preview keeps data for this session only. For persistent imports and saves, open the private local app.');return}return new Promise((res,rej)=>{let tx=database.transaction(store,'readwrite');tx.objectStore(store).put(item);tx.oncomplete=res;tx.onabort=()=>rej(tx.error)})}
function route(){let k=location.hash.slice(1);if(!pages[k])k='market';serial++;({market,test:backtester,compare:comparison,angel,depth,contact})[k]();window.scrollTo(0,0)}
function importDialog(){modal('Import historical prices',note('Import one instrument per UTF-8 CSV. Daily files use date,open,close. One-minute files use date,time,open,high,low,close. Dates use YYYY-MM-DD and start-of-minute times use HH:MM in IST. Optional symbol must match every row.')+'<form id="importer"><div class="fields">'+input('Instrument / exact contract symbol','isym','RELIANCE','text','maxlength="90"')+select('Asset type','asset',['Equity','Index','Future','Option contract'])+'<label hidden id="exLabel">Contract expiry<input id="iex" type="date"></label><label hidden id="strikeLabel">Strike price<input id="isk" type="number" min="0.01" step="any"></label>'+input('Data source','provider','','text','placeholder="e.g. broker export"')+input('CSV file','upload','','file','accept=".csv,text/csv"')+'</div>'+note('For options enter the full exchange contract identifier, including expiry, strike and CE/PE. Import observed contract premiums. Daily candles are available in Market Returns only.')+'<button class="primary">Import prices</button> <button type="button" onclick="fixture()">Download example CSV</button><p id="imsg" role="status"></p></form>');$('asset').onchange=()=>{let opt=$('asset').value==='Option contract';for(let [a,b] of [['exLabel','iex'],['strikeLabel','isk']]){$(a).hidden=!opt;$(b).required=opt}};$('importer').onsubmit=async e=>{e.preventDefault();try{let f=$('upload').files[0],s=$('isym').value.trim().toUpperCase(),kind=$('asset').value,src=$('provider').value.trim();if(!s||!src)throw Error('Enter an instrument and source.');if(kind==='Option contract'&&(!/\d/.test(s)||!/(CE|PE)/.test(s)))throw Error('Use the exact expiry/strike/CE or PE contract symbol.');let raw=await f.text(),data=parseFile(raw,s),item={id:crypto.randomUUID(),s,kind,src,expiry:$('iex').value,strike:+$('isk').value,name:f.name,...data};await persist('files',item);imports.push(item);marketSymbol=s;chosen=item.id;Object.assign(filters,{from:item.rows[0].d,to:item.rows.at(-1).d,cap:kind==='Index'?'Indices':'All stocks',query:s,period:'Custom'});dlg.close();route()}catch(err){$('imsg').textContent=err.message}}}
function fixture(){csv('demo-minute-candles',[['date','time','open','high','low','close'],...['2026-10-30','2026-11-02'].flatMap((d,j)=>Array.from({length:6},(_,i)=>[d,timeOf(570+i),100+j+i,102+j+i,99+j+i,101+j+i]))])}
function symbolList(){return [...new Set([...all,...imports.map(x=>x.s)])]}
function market(){let f=imports.find(x=>x.id===chosen&&x.s===marketSymbol)||imports.filter(x=>x.s===marketSymbol).at(-1),lookup=()=>f?dailyBars(f.rows):all.includes(marketSymbol)?historyFor(marketSymbol):[],rs=lookup(),until=rs.at(-1)?.d||end;
$('app').innerHTML=heading('Market research','Market Returns','Explore session moves and compounded performance.',importButton)+'<section class="panel"><div class="fields">'+input('Search instrument','ms',marketSymbol,'search','list="universe"')+'<datalist id="universe">'+symbolList().map(s=>'<option value="'+esc(s)+'">').join('')+'</datalist>'+select('Period','period',['7 days','1 year','2 years','Custom'])+input('From','mf',rs[0]?.d||start,'date')+input('Through','mt',until,'date')+'</div><div id="mout"></div></section>';let refresh=()=>{let sym=$('ms').value.trim().toUpperCase();if(sym!==marketSymbol){marketSymbol=sym;market();return}marketRange=$('period').value;let custom=marketRange==='Custom',t=custom?$('mt').value:until,dt=new Date(t+'T00:00:00Z');if(!custom){if(marketRange==='7 days')dt.setUTCDate(dt.getUTCDate()-6);else dt.setUTCFullYear(dt.getUTCFullYear()-(marketRange==='1 year'?1:2));$('mf').value=dt.toISOString().slice(0,10);$('mt').value=until}for(let id of ['mf','mt'])$(id).disabled=!custom;let rows=rs.filter(r=>r.d>=$('mf').value&&r.d<=t),daily=1,actual=1;rows=rows.map(r=>{daily*=1+r.i/100;if(r.a!=null)actual*=1+r.a/100;return {...r,ci:(daily-1)*100,ca:r.a==null?null:(actual-1)*100}});let last=rows.at(-1),src=f?'CSV · '+esc(f.src)+' · '+esc(f.name):marketSymbol==='SENSEX'?'Historical · Investing.com Sensex daily snapshot':'Demo · synthetic daily prices';$('mout').innerHTML=note('Source: '+src+' &nbsp; | &nbsp; Coverage: '+(rs.length?rs[0].d+' to '+until+' · '+rs.length+' observed sessions':'unavailable')+(f?.minute?' · daily open/close from imported minute coverage':'') )+(last?metrics([['Last close','₹'+fmt(last.c)],['Latest intraday',pct(last.i)],['Latest actual return',pct(last.a)],['Cumulative actual',pct(last.ca)]])+'<div class="row"><h2>Cumulative performance</h2><select id="series" aria-label="Cumulative return series"><option>Actual return</option><option>Intraday return</option></select></div><div id="mchart"></div><div class="row"><h2>Daily returns</h2><button id="mexport">↓ Export results</button></div>'+table(['Session','Open','Close','Intraday','Actual','Cumulative intraday','Cumulative actual'],rows.slice().reverse().map(r=>[r.d,fmt(r.o),fmt(r.c),pct(r.i),pct(r.a),pct(r.ci),pct(r.ca)]))+note('Intraday = (close − open) / open. Actual = (close − previous observed session close) / previous close. Each cumulative series compounds its daily returns. An unavailable starting return is omitted.') :empty('No observed sessions for this instrument and range.'));if(last){let chart=()=>{let k=$('series').selectedIndex?'ci':'ca';$('mchart').innerHTML=plot(rows.filter(r=>r[k]!=null),k)};$('series').onchange=chart;chart();$('mexport').onclick=()=>csv('market-returns',[['Symbol','Date','Open','Close','Intraday %','Actual %','Cumulative intraday %','Cumulative actual %'],...rows.map(r=>[marketSymbol,r.d,r.o,r.c,r.i,r.a,r.ci,r.ca])])}};$('period').value=marketRange;$('ms').onchange=refresh;['period','mf','mt'].forEach(id=>$(id).onchange=refresh);refresh()}

